  '{1}: Bar over mid-foot, shins touch it, flat back, pull the slack out, push the floor away, bar stays on the legs, stand tall.':
    '{1}: kang jalalaba keskosa kohal, sääred puudutavad seda, sirge selg, võta lõtk välja, lükka põrand eemale, kang püsib vastu jalgu, tõuse täiesti sirgeks.',
  '{1}: Eyes under the bar, shoulder blades squeezed and down, feet planted, bar to the lower chest, elbows ~{2}–{3}°, press up and slightly back.':
    '{1}: silmad kangi all, abaluud kokku ja alla, jalad maas, kang rinna alaossa, küünarnukid ~{2}–{3}°, suru üles ja veidi taha.',
  '{1}: Feet shoulder-width, toes slightly out.':
    '{1}: jalad õlgade laiuselt, varbad veidi väljas.',
  '{1}: Grip just outside shoulders, squeeze glutes, ribs down, press straight up, head through at the top.':
    '{1}: haare veidi õlgadest laiemalt, pigista tuharad kokku, ribid alla, suru otse üles, pea üleval läbi.',
  '{1}: Hinge to ~{2}°, flat back, pull the bar to the lower ribs, elbows back, squeeze the shoulder blades.':
    '{1}: kallutu ~{2}°-ni, sirge selg, tõmba kang alumiste ribide juurde, küünarnukid taha, pigista abaluud kokku.',
